  ["e5057f89f25feb05"] = { "Imparerai, {name}, e un giorno sarai <un/una> grande {class}.", "." },
  ["e50aba6648051769"] = { "Di ritorno da un lungo viaggio? Riposati e rilassati al Pig and Whistle!", "." },
