  ["e51f8c56ede28d36"] = { "Mio! Mio! Mio! ⟦Gizlock=Tagliafizz⟧ è il signore di questo dominio! Non rivelerai mai la mia presenza!", "." },
  ["e5274aa273553290"] = { "Devi affrettarti verso lo Stagno dei Draghi, {name}. Con le uova di Onyxia sparse per il ⟦Wyrmbog=Brago dei Dragoni⟧, ci troveremo davanti a un numero schiacciante di nemici se non si fa qualcosa in fretta.\n\nDistruggi le sue uova! Non lasciare che la piaga dei draghi neri si diffonda nella nostra terra!", "." },
  ["e5286cb381fbc131"] = { "%s si riaccende grazie al calore di un altro Core Hound!", "." },
  ["e52c83f5734496ee"] = { "Ma dove, nelle Terre Esterne, sono finite quelle spedizioni? Sono giorni che mi fanno aspettare!", "." },
  ["e52da0f002e5066b"] = { "Zul'jin un giorno tornerà, {race}. Ricorda le mie parole. Fino ad allora, manteniamo tutti le nostre posizioni e facciamo il possibile per preservare la popolazione dei troll della foresta.\n\nDetto questo, come capocaccia del ⟦Revantusk Village=Villaggio degli Zannatorta⟧, è mia responsabilità garantire che il mondo intorno a noi sia sicuro per viverci.\n\nLe bestie di questa zona vanno tenute sotto controllo.\n\nCerchi lavoro?", "." },
  ["e52e77b4049bb3ea"] = { "Posso aiutarti a trovare qualcosa, <cittadino/cittadina>?", "." },
  ["e5351497aba93b38"] = { "Ben <trovato/trovata>, {class}. Vuoi un consiglio? Fai amicizia con un mago! Abbiamo qualche asso nella manica, eccome...", "." },
  ["e54047254e30ba30"] = { "No, non posso aiutarti, temo. Le tue abilità hanno superato le mie! Se vuoi imparare di più, parla con l'elfo della notte Telonis alla ⟦Craftsmen's Terrace=Terrazza degli Artigiani⟧ di Darnassus. È straordinario!", "." },
  ["e54bbb6b5da5d2fa"] = { "Ce l'abbiamo fatta! Abbiamo vinto!", "." },
  ["e550709d2823ffcd"] = { "A me sembra una delle storie di pesca di Billy.", "." },
  ["e557a9c52e7eaa68"] = { "Salute, {class}. Sono Leoren, stalliere della ⟦Cenarion Hold=Fortezza Cenariana⟧.", "." },
  ["e55a1a100aa85c6d"] = { "⟦Tower Point=Torre Granguardia⟧ controlla il passo tra il ⟦Field of Strife=Pian della Discordia⟧ e i territori dell'⟦Horde=Orda⟧ a sud.\n\nÈ controllata dall'⟦Alliance=Alleanza⟧.", "." },
  ["e55b98727d0a31f0"] = { "Grazie, nobile {class}.", "." },
  ["e55dfbfb675b8f24"] = { "%s si inchina davanti a Krang Stonehoof", "." },
  ["e55fed8e0cba020f"] = { "Tutti i tipi da furfanti bazzicano The Forlorn Cavern, a nord dei cancelli di ⟦Ironforge=Forgiardente⟧. Scommetto che ci troverai Fenthwick, di sicuro intento a contare le monete di un altro borseggiatore. Uno di questi giorni lo acchiappo!\n\nNel frattempo terrò d'occhio anche te, <ragazzo/ragazza>.", "." },
  ["e5627e6b4d12267f"] = { "Sull'attenti, soldato!\n\nWINKY! RAPPORTO!", "." },
  ["e56db50d49d03188"] = { "Ecco fatto...", "." },
  ["e56dc4f702a8ddca"] = { "Il tuo destino è segnato, Deliana! Pagherai per i tuoi oltraggi contro lord Valthalak!", "." },
  ["e57154b4dc5899a1"] = { "La Madre Terra mi ha mandato dei segni: hai fatto un buon lavoro.", "." },
  ["e577ee56a2877042"] = { "Potenziamento a unità veterane!", "." },
  ["e57b8d0280bf2cf0"] = { "Senti il richiamo della caccia, {class}? Devi ascoltare con attenzione, ma il richiamo viene dal profondo di te. Viene dal profondo di tutti noi.", "." },
  ["e57f9d65bff20883"] = { "Dove pensavi che fosse il maestro delle viverne? Va' in cima alla Sky Tower nella ⟦Valley of Strength=Valle della Forza⟧!", "." },
  ["e581a55da6659009"] = { "Non posso mostrarti come controllare un'ombra del Vuoto finché non ne avrai sottomessa una.", "." },
  ["e593ad53b09df6bc"] = { "Cosa? Vuoi dire che questo non riesci a ucciderlo con le tue sole forze?", "." },
  ["e599f76ad5659214"] = { "Credi di poterci evocare? Siamo noi che evochiamo, non tu! Ti pestiamo per bene per questo e ti succhiamo il midollo dalle ossa!", "." },
  ["e59d3aba546b43ad"] = { "Ti serve un'illusione?\n\nSe la tua illusione dovesse svanire nel bel mezzo della tua missione, torna da me e ti ridarò il travestimento.\n\nSe dovessi fallire nelle tue imprese, non arrenderti! Torna da me. Ti aiuterò finché non avrai completato i tuoi obiettivi.", "." },
  ["e5a3afc7a4a3e743"] = { "Nella scatola, miei tesori! Così. Uno alla volta.", "." },
  ["e5aa4e553f7acba8"] = { "Bah! Altro fallimento!", "." },
  ["e5ac3e9fe480d270"] = { "Insegnare non è uno scambio a senso unico, {name}. Mentre ti insegno, imparo anch'io, e la mia comprensione cresce.", "." },
  ["e5b778d96931c9c8"] = { "Rin'ji ti dice segreto ora... {name} deve andare alla Scogliera Altosguardo. Rin'ji ha nascosto qualcosa su isola là.", "." },
  ["e5bd0d6207f21b5c"] = { "Salve, Rutgar. Il comandante mi ha mandato qui a raccogliere informazioni sulla moglie scomparsa.", "." },
  ["e5be11aa0c9e171c"] = { "Ho perso il mio ⟦Hammer of the Gathering Storm=Martello della Tempesta Crescente⟧. Puoi sostituirmelo?", "." },
  ["e5bed1d8fe46c2e6"] = { "Qui si riscattano i biglietti! Trasforma i tuoi biglietti in premi! Fatti avanti!", "." },
  ["e5c38af53c8ecfc1"] = { "Ecco fatto, ora puoi creare una Sharpening Wheel tutta tua. Alla maggior parte della gente non piace che si piantino accampamenti in mezzo al paese, quindi dovrai andare nelle terre selvagge se vuoi provarla.\n\nAh, e ricorda: nessun accampamento è completo senza un fuoco. Te ne servirà uno prima di allestire il tuo accampamento. Quasi tutti i cuochi possono insegnarti ad accendere un fuoco. Se non l'hai già fatto, faresti bene a passare da qualcuno che possa istruirti nell'arte culinaria per imparare le basi.", "." },
  ["e5c8150fb77d7bec"] = { "Non ora. Hai qualche incarico per me?", "." },
  ["e5d0230c48c30a68"] = { "<Benvenuto/Benvenuta> alla ⟦Great Forge=Grande Forgia⟧, <ragazzo/ragazza>. Fuori farà anche freddo, ma qui sotto lo teniamo bello caldo. Prendi un martello, colpisci quell'incudine e mostrami che hai la stoffa per essere un Fabbro della ⟦Great Forge=Grande Forgia⟧!", "." },
  ["e5d5708eccbcd53e"] = { "Oh, mi spiace, ma a questo punto ne sai più tu di cuoio di me. Parla con Faldron, laggiù, se vuoi imparare di più.", "." },
  ["e5dbebcf5cd41ef1"] = { "%s va su tutte le furie vedendo morire un cucciolo!", "." },
  ["e5de72b8ea9c61af"] = { "Tu! Gettati nella mischia!", "." },
  ["e5e63056373f5d77"] = { "Salute, amico! Ho un'ampia scorta di cuoio e pelli, e conosco qualche tecnica che potrei anche condividere. Ti interessa fare affari?", "." },
  ["e5f7e7a0bb888ca6"] = { "I tuoi dèi non possono salvarti ora, {class}.", "." },
  ["e5fdaf6791e1ed8d"] = { "Un po' di tutto. Soprattutto prendo i deboli e i molli e li riplasmo di nuovo in combattenti temprati.\r\n\nLà fuori il mondo è duro, e perfino la nostra gente diffida di noi. Dobbiamo essere duri e autosufficienti, se vogliamo trovare posto in quest'\"orda\" insieme al resto del nostro popolo.", "." },
